export interface ConnectorConfig {
  slackBotToken: string
  fetch?: typeof fetch
}

export interface TwilioWebhookPayload {
  Body: string
  From: string
  To: string
}

export interface SlackMessageResult {
  ok: boolean
  channel: string
  ts: string
}

export interface HandleResult {
  channel: string
  slackResponse: SlackMessageResult
}

const SALES_KEYWORDS = /pricing|quote|demo/i

function parseFormBody(body: string): Record<string, string> {
  const params = new URLSearchParams(body)
  const result: Record<string, string> = {}
  for (const [key, value] of params.entries()) {
    result[key] = value
  }
  return result
}

function validatePayload(payload: unknown): TwilioWebhookPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Invalid payload: expected an object')
  }
  const p = payload as Record<string, unknown>
  if (typeof p.Body !== 'string' || p.Body.trim() === '') {
    throw new Error('Missing required field: Body')
  }
  if (typeof p.From !== 'string' || p.From.trim() === '') {
    throw new Error('Missing required field: From')
  }
  return {
    Body: p.Body,
    From: p.From,
    To: typeof p.To === 'string' ? p.To : '',
  }
}

function determineChannel(body: string): string {
  return SALES_KEYWORDS.test(body) ? '#sales' : '#support'
}

async function sendSlackMessage(
  config: ConnectorConfig,
  channel: string,
  text: string,
): Promise<SlackMessageResult> {
  const fetchFn = config.fetch ?? fetch
  const url = 'https://slack.com/api/chat.postMessage'
  const body = JSON.stringify({ channel, text })
  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${config.slackBotToken}`,
    },
    body,
  })
  if (!response.ok) {
    throw new Error(`Slack API error: ${response.status} ${response.statusText} at ${url}`)
  }
  return (await response.json()) as SlackMessageResult
}

export async function handle(
  payload: unknown,
  config: ConnectorConfig,
): Promise<HandleResult> {
  if (!config.slackBotToken) {
    throw new Error('Missing required config: slackBotToken')
  }
  const validated = validatePayload(payload)
  const channel = determineChannel(validated.Body)
  const slackResponse = await sendSlackMessage(config, channel, validated.Body)
  return { channel, slackResponse }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, TwilioWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test-token',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as TwilioWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.channel).toBe('#sales')
    expect(result.slackResponse.ok).toBe(true)
  })
})

describe('handle', () => {
  let calls: RecordedCall[]
  let fetch: typeof fetch
  let baseConfig: ConnectorConfig

  beforeEach(() => {
    const fake = fakeFetch((req) => {
      if (req.url === 'https://slack.com/api/chat.postMessage' && req.method === 'POST') {
        return jsonResponse({ ok: true, channel: req.json?.channel, ts: '1234567890.123456' })
      }
      return jsonResponse({ error: 'not found' }, 404)
    })
    fetch = fake.fetch
    calls = fake.calls
    baseConfig = { slackBotToken: 'xoxb-test-token', fetch }
  })

  it('routes pricing keyword to #sales', async () => {
    const payload: TwilioWebhookPayload = {
      Body: 'I need pricing for your product',
      From: '+15551234567',
      To: '+15559876543',
    }
    const result = await handle(payload, baseConfig)
    expect(result.channel).toBe('#sales')
    expect(calls[0].json).toEqual({ channel: '#sales', text: payload.Body })
    expect(calls[0].headers.get('authorization')).toBe('Bearer xoxb-test-token')
  })

  it('routes quote keyword to #sales', async () => {
    const payload: TwilioWebhookPayload = {
      Body: 'Please send me a quote',
      From: '+15551234567',
      To: '+15559876543',
    }
    const result = await handle(payload, baseConfig)
    expect(result.channel).toBe('#sales')
    expect(calls[0].json).toEqual({ channel: '#sales', text: payload.Body })
  })

  it('routes demo keyword to #sales', async () => {
    const payload: TwilioWebhookPayload = {
      Body: 'Can I schedule a demo?',
      From: '+15551234567',
      To: '+15559876543',
    }
    const result = await handle(payload, baseConfig)
    expect(result.channel).toBe('#sales')
    expect(calls[0].json).toEqual({ channel: '#sales', text: payload.Body })
  })

  it('routes non-matching message to #support', async () => {
    const payload: TwilioWebhookPayload = {
      Body: 'Hello, I have a general question',
      From: '+15551234567',
      To: '+15559876543',
    }
    const result = await handle(payload, baseConfig)
    expect(result.channel).toBe('#support')
    expect(calls[0].json).toEqual({ channel: '#support', text: payload.Body })
  })

  it('throws on missing Body field', async () => {
    const payload = { From: '+15551234567', To: '+15559876543' }
    await expect(handle(payload as unknown as TwilioWebhookPayload, baseConfig)).rejects.toThrow(
      'Missing required field: Body',
    )
  })

  it('throws on missing From field', async () => {
    const payload = { Body: 'Hello', To: '+15559876543' }
    await expect(handle(payload as unknown as TwilioWebhookPayload, baseConfig)).rejects.toThrow(
      'Missing required field: From',
    )
  })

  it('throws on empty Body field', async () => {
    const payload: TwilioWebhookPayload = { Body: '', From: '+15551234567', To: '+15559876543' }
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: Body')
  })

  it('throws on missing slackBotToken', async () => {
    const payload: TwilioWebhookPayload = {
      Body: 'Hello',
      From: '+15551234567',
      To: '+15559876543',
    }
    const config: ConnectorConfig = { slackBotToken: '', fetch }
    await expect(handle(payload, config)).rejects.toThrow('Missing required config: slackBotToken')
  })

  it('throws on Slack API non-2xx response', async () => {
    const errorFetch = fakeFetch(() => jsonResponse({ error: 'invalid_token' }, 401))
    const config: ConnectorConfig = { slackBotToken: 'bad-token', fetch: errorFetch.fetch }
    const payload: TwilioWebhookPayload = {
      Body: 'Hello',
      From: '+15551234567',
      To: '+15559876543',
    }
    await expect(handle(payload, config)).rejects.toThrow(
      'Slack API error: 401 Unauthorized at https://slack.com/api/chat.postMessage',
    )
  })

  it('uses injected fetch over global fetch', async () => {
    const customFetch = fakeFetch((req) =>
      jsonResponse({ ok: true, channel: '#sales', ts: '1234567890.123456' }),
    )
    const config: ConnectorConfig = { slackBotToken: 'token', fetch: customFetch.fetch }
    const payload: TwilioWebhookPayload = {
      Body: 'Need a quote',
      From: '+15551234567',
      To: '+15559876543',
    }
    await handle(payload, config)
    expect(customFetch.calls.length).toBe(1)
  })
})

